WITH matched_keys AS (SELECT id, channel FROM promotions EXCEPT ALL SELECT id, channel FROM promotions WHERE discount_pct <= 0.29), reconciled AS (SELECT s.* FROM promotions s INNER JOIN matched_keys k ON s.id = k.id AND s.channel = k.channel) SELECT promo_code, CASE WHEN discount_pct >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_pct_tier, MAX(discount_pct) AS max_discount_pct, ROUND(SUM(discount_pct) / NULLIF(COUNT(CASE WHEN promo_code = 'BUNDLE' THEN 1 END), 0), 2) AS discount_pct_per_bundle, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, COUNT(*) AS row_count, MAX(discount_pct) AS max_discount_pct_2, SIZE(COLLECT_SET(promo_code)) AS num_promo_codes, GROUPING_ID() AS gid FROM reconciled GROUP BY ROLLUP (promo_code, CASE WHEN discount_pct >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING SIZE(COLLECT_SET(promo_code)) >= 1;
